// 轻量级 Markdown 解析器
(function(global) {
  'use strict';

  function escapeHtml(text) {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function parseMarkdown(text) {
    if (!text) return '';

    let html = text;

    // 转义 HTML 特殊字符（除了代码块中的内容）
    // 先处理代码块
    const codeBlocks = [];
    html = html.replace(/```([\s\S]*?)```/g, function(match, code) {
      const trimmed = code.trim();
      // 如果是 ```markdown 开头，提取内容并作为普通 markdown 处理
      if (trimmed.toLowerCase().startsWith('markdown\n')) {
        const markdownContent = trimmed.slice(9).trim();
        return markdownContent;
      }
      codeBlocks.push('<pre><code>' + escapeHtml(trimmed) + '</code></pre>');
      return '\x00CODE' + (codeBlocks.length - 1) + '\x00';
    });

    // 处理行内代码
    const inlineCodes = [];
    html = html.replace(/`([^`]+)`/g, function(match, code) {
      inlineCodes.push('<code>' + escapeHtml(code) + '</code>');
      return '\x00INLINE' + (inlineCodes.length - 1) + '\x00';
    });

    // 处理表格
    const tables = [];
    html = html.replace(/((?:^\|[^\n]*\|\n)+)/gm, function(match, tableContent) {
      const lines = tableContent.trim().split('\n');
      if (lines.length < 2) return match;

      // 检查第二行是否是分隔符行 (|------|------|)
      const separatorLine = lines[1].trim();
      if (!separatorLine.match(/^\|[-:\s|]+\|$/)) return match;

      // 解析行内 markdown（加粗、斜体、链接等）
      function parseInline(text) {
        return text
          .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
          .replace(/__([^_]+)__/g, '<strong>$1</strong>')
          .replace(/\*([^*]+)\*/g, '<em>$1</em>')
          .replace(/_([^_]+)_/g, '<em>$1</em>')
          .replace(/~~([^~]+)~~/g, '<del>$1</del>')
          .replace(/`([^`]+)`/g, '<code>$1</code>');
      }

      let tableHtml = '<table>';

      // 处理表头
      const headers = lines[0].split('|').map(s => s.trim()).filter(s => s);
      tableHtml += '<thead><tr>';
      headers.forEach(header => {
        tableHtml += '<th>' + parseInline(escapeHtml(header)) + '</th>';
      });
      tableHtml += '</tr></thead>';

      // 处理表身
      tableHtml += '<tbody>';
      for (let i = 2; i < lines.length; i++) {
        const cells = lines[i].split('|').map(s => s.trim()).filter(s => s);
        if (cells.length > 0) {
          tableHtml += '<tr>';
          cells.forEach(cell => {
            tableHtml += '<td>' + parseInline(escapeHtml(cell)) + '</td>';
          });
          tableHtml += '</tr>';
        }
      }
      tableHtml += '</tbody></table>';

      tables.push(tableHtml);
      return '\x00TABLE' + (tables.length - 1) + '\x00';
    });

    // 处理标题
    html = html.replace(/^###### (.*$)/gim, '<h6>$1</h6>');
    html = html.replace(/^##### (.*$)/gim, '<h5>$1</h5>');
    html = html.replace(/^#### (.*$)/gim, '<h4>$1</h4>');
    html = html.replace(/^### (.*$)/gim, '<h3>$1</h3>');
    html = html.replace(/^## (.*$)/gim, '<h2>$1</h2>');
    html = html.replace(/^# (.*$)/gim, '<h1>$1</h1>');

    // 处理粗体
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/__([^_]+)__/g, '<strong>$1</strong>');

    // 处理斜体
    html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
    html = html.replace(/_([^_]+)_/g, '<em>$1</em>');

    // 处理删除线
    html = html.replace(/~~([^~]+)~~/g, '<del>$1</del>');

    // 处理链接
    html = html.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank">$1</a>');

    // 处理图片
    html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img alt="$1" src="$2" style="max-width:100%;">');

    // 处理引用块
    html = html.replace(/^\> (.*$)/gim, '<blockquote>$1</blockquote>');

    // 处理列表（支持嵌套和多行内容）
    function parseLists(text) {
      const lines = text.split('\n');
      const result = [];
      const listStack = []; // 存储列表状态 { type: 'ul'|'ol', indent: number }
      let currentLiContent = null;
      let currentLiIndent = 0;

      function isListItem(line) {
        return line.match(/^(\s*)[-*] /) || line.match(/^(\s*)\d+\. /);
      }

      function flushLi() {
        if (currentLiContent !== null) {
          result.push(`<li>${currentLiContent.join(' ')}</li>`);
          currentLiContent = null;
        }
      }

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const trimmed = line.trim();

        // 检测列表项
        const unorderedMatch = line.match(/^(\s*)[-*] (.*)$/);
        const orderedMatch = line.match(/^(\s*)(\d+)\. (.*)$/);

        if (unorderedMatch || orderedMatch) {
          const match = unorderedMatch || orderedMatch;
          const indent = match[1].length;
          const isOrdered = !!orderedMatch;
          let content = unorderedMatch ? match[2] : match[3];

          // 确定当前列表类型
          const listType = isOrdered ? 'ol' : 'ul';

          // 先刷新之前的列表项
          flushLi();

          // 处理列表层级变化
          if (listStack.length === 0) {
            // 开始新列表
            listStack.push({ type: listType, indent: indent });
            result.push(`<${listType}>`);
          } else {
            const lastList = listStack[listStack.length - 1];

            if (indent > lastList.indent) {
              // 进入更深层级
              listStack.push({ type: listType, indent: indent });
              result.push(`<${listType}>`);
            } else if (indent < lastList.indent) {
              // 返回更浅层级
              while (listStack.length > 0 && listStack[listStack.length - 1].indent > indent) {
                flushLi();
                const closing = listStack.pop();
                result.push(`</${closing.type}>`);
              }
              // 检查是否需要切换列表类型
              const currentList = listStack[listStack.length - 1];
              if (currentList && currentList.indent === indent && currentList.type !== listType) {
                flushLi();
                const closing = listStack.pop();
                result.push(`</${closing.type}>`);
                listStack.push({ type: listType, indent: indent });
                result.push(`<${listType}>`);
              } else if (listStack.length === 0 || listStack[listStack.length - 1].indent < indent) {
                listStack.push({ type: listType, indent: indent });
                result.push(`<${listType}>`);
              }
            } else if (lastList.type !== listType) {
              // 同层级但类型不同，关闭旧列表，开启新列表
              flushLi();
              const closing = listStack.pop();
              result.push(`</${closing.type}>`);
              listStack.push({ type: listType, indent: indent });
              result.push(`<${listType}>`);
            }
          }

          // 开始新的列表项
          currentLiContent = [content];
          currentLiIndent = indent;
        } else if (currentLiContent !== null) {
          // 当前在列表项中，检查是否是续行
          const lineIndent = line.match(/^(\s*)/)?.[1].length || 0;

          // 如果是空行或缩进足够的行，视为列表项的续行
          if (trimmed === '') {
            // 检查下一行是否继续当前列表
            const nextLine = lines[i + 1];
            if (nextLine) {
              const nextMatch = isListItem(nextLine);
              const nextIndent = nextLine.match(/^(\s*)/)?.[1].length || 0;

              if (!nextMatch || nextIndent <= currentLiIndent) {
                // 列表项结束
                flushLi();
              } else {
                // 继续列表项，保留空行
                currentLiContent.push('');
              }
            } else {
              flushLi();
            }
          } else if (lineIndent > currentLiIndent) {
            // 缩进更多，是续行
            currentLiContent.push(line.trim());
          } else if (!isListItem(line)) {
            // 不是列表项且缩进不够，列表结束
            flushLi();
            // 关闭所有列表
            while (listStack.length > 0) {
              const closing = listStack.pop();
              result.push(`</${closing.type}>`);
            }
            result.push(line);
          } else {
            // 是新的列表项，flushLi 会在下一轮处理
            flushLi();
          }
        } else if (trimmed === '' && listStack.length > 0) {
          // 空行，检查下一行是否继续列表
          const nextLine = lines[i + 1];
          if (nextLine) {
            if (!isListItem(nextLine)) {
              // 列表结束
              flushLi();
              while (listStack.length > 0) {
                const closing = listStack.pop();
                result.push(`</${closing.type}>`);
              }
              result.push('');
            } else {
              result.push('');
            }
          } else {
            // 文件结束
            flushLi();
            while (listStack.length > 0) {
              const closing = listStack.pop();
              result.push(`</${closing.type}>`);
            }
            result.push('');
          }
        } else {
          result.push(line);
        }
      }

      // 关闭所有未关闭的内容
      flushLi();
      while (listStack.length > 0) {
        const closing = listStack.pop();
        result.push(`</${closing.type}>`);
      }

      return result.join('\n');
    }

    html = parseLists(html);

    // 处理分隔线
    html = html.replace(/^---$/gim, '<hr>');
    html = html.replace(/^\*\*\*$/gim, '<hr>');
    html = html.replace(/^___$/gim, '<hr>');

    // 处理段落（在行之间添加 p 标签）
    const lines = html.split('\n');
    const result = [];
    let inParagraph = false;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();

      if (!line) {
        if (inParagraph) {
          result.push('</p>');
          inParagraph = false;
        }
        continue;
      }

      // 如果行已经是块级元素，不包裹在 p 中
      if (line.match(/^<(h[1-6]|ul|ol|li|blockquote|pre|hr)/)) {
        if (inParagraph) {
          result.push('</p>');
          inParagraph = false;
        }
        result.push(line);
      } else if (line.match(/<\/(h[1-6]|ul|ol|li|blockquote|pre|hr)>$/)) {
        result.push(line);
        inParagraph = false;
      } else {
        if (!inParagraph) {
          result.push('<p>');
          inParagraph = true;
        }
        result.push(line);
      }
    }

    if (inParagraph) {
      result.push('</p>');
    }

    html = result.join('\n');

    // 替换代码块占位符
    html = html.replace(/\x00CODE(\d+)\x00/g, function(match, index) {
      return codeBlocks[parseInt(index)];
    });

    // 替换表格占位符
    html = html.replace(/\x00TABLE(\d+)\x00/g, function(match, index) {
      return tables[parseInt(index)];
    });

    // 替换行内代码占位符
    html = html.replace(/\x00INLINE(\d+)\x00/g, function(match, index) {
      return inlineCodes[parseInt(index)];
    });

    return html;
  }

  // 暴露 API
  const marked = {
    parse: function(text, options) {
      return parseMarkdown(text);
    },
    parseInline: function(text) {
      return parseMarkdown(text);
    },
    setOptions: function(options) {
      // 为了保持兼容，接受设置但暂时不使用
    }
  };

  // 导出
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = marked;
  } else if (typeof define === 'function' && define.amd) {
    define(function() { return marked; });
  } else {
    global.marked = marked;
  }

})(typeof globalThis !== 'undefined' ? globalThis : typeof window !== 'undefined' ? window : this);
